"""Curated V1 archetypes for the first four FORGE India atlas domains.

This module is intentionally data-only.  The generator in
``forge.india_v1.generator`` expands these compatible family axes into a
stable, reusable atlas.  The records are broad navigation and dependency
primitives, not facility-level capability claims; the baseline status for each
archetype is therefore marked as an explicit curated assumption downstream.

The four domains are presentation views over one graph.  Cross-domain
materials, processes, equipment, capabilities, and infrastructure are defined
once in ``SHARED_PRIMITIVES`` and referenced by every domain that uses them.
"""
from __future__ import annotations

from typing import Any, Dict, List


def _a(
    slug: str,
    name: str,
    category: str,
    profile: str,
    status: str,
    uses: List[str],
    *,
    aliases: List[str] | None = None,
    gap: str = "Specification fit, qualified effective capacity, and supplier allocation require evidence before a stronger claim.",
) -> Dict[str, Any]:
    """Compact archetype declaration used by the deterministic generator."""

    return {
        "slug": slug,
        "name": name,
        "category": category,
        "profile": profile,
        "status": status,
        "uses": list(uses),
        "aliases": list(aliases or []),
        "gap": gap,
    }


